select count(*) as schemas from pg_namespace;
select count(*) as info_schema_tables from information_schema.tables;
\echo '===== 最终测量（explain analyze，取 Execution Time）====='
\echo 'M1 information_schema.tables 全量扫描：'
explain (analyze, format text) select count(*) from information_schema.tables;
\echo 'M2 information_schema.tables 精确到单个 schema：'
explain (analyze, format text) select table_name from information_schema.tables where table_schema = 't_0001';
\echo 'M3 pg_class 按 schema 点查：'
explain (analyze, format text) select relname from pg_class where relnamespace = to_regnamespace('t_0001');
\echo 'M4 单租户业务查询（空表 count）：'
explain (analyze, format text) select count(*) from t_0042.orders;
\echo 'M5 再建一个租户 schema + 表的 DDL 耗时：'
\timing on
CREATE SCHEMA t_9500;
CREATE TABLE t_9500.orders (id bigint primary key, amount numeric(12,2));
\timing off
\echo 'M6 库大小：'
select pg_size_pretty(pg_database_size(current_database())) as db_size;